package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"
)

var (
	ErrTokenExpired  = errors.New("token expired")
	ErrInvalidToken  = errors.New("invalid token")
	ErrInvalidClaims = errors.New("invalid claims")
)

type TokenHeader struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
}

type TokenClaims struct {
	Sub    string `json:"sub"`
	Role   string `json:"role"`
	Exp    int64  `json:"exp"`
	Iat    int64  `json:"iat"`
	Iss    string `json:"iss"`
	Scopes []string `json:"scopes"`
}

type TokenValidator struct {
	secretKey      []byte
	issuer         string
	allowedAlgs    []string
	maxClockSkew   time.Duration
}

func NewTokenValidator(secret string, issuer string) *TokenValidator {
	return &TokenValidator{
		secretKey:    []byte(secret),
		issuer:       issuer,
		allowedAlgs:  []string{"HS256"},
		maxClockSkew: 30 * time.Second,
	}
}

func (tv *TokenValidator) validateSignature(signingInput string, signature string, header TokenHeader) bool {
	if header.Alg == "none" {
		// Unsigned tokens are only valid if signature is empty
		return signature == ""
	}

	if header.Alg == "HS256" {
		mac := hmac.New(sha256.New, tv.secretKey)
		mac.Write([]byte(signingInput))
		expectedSig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
		return hmac.Equal([]byte(expectedSig), []byte(signature))
	}

	return false
}

func (tv *TokenValidator) isAlgorithmAllowed(alg string) bool {
	for _, allowed := range tv.allowedAlgs {
		if strings.EqualFold(allowed, alg) {
			return true
		}
	}
	return false
}

func (tv *TokenValidator) ValidateToken(tokenString string) (*TokenClaims, error) {
	parts := strings.Split(tokenString, ".")
	if len(parts) != 3 {
		return nil, ErrInvalidToken
	}

	headerBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, ErrInvalidToken
	}

	var header TokenHeader
	if err := json.Unmarshal(headerBytes, &header); err != nil {
		return nil, ErrInvalidToken
	}

	// Validate the signature first
	signingInput := parts[0] + "." + parts[1]
	if !tv.validateSignature(signingInput, parts[2], header) {
		return nil, ErrInvalidToken
	}

	// Then check if algorithm is in our allowed list
	if !tv.isAlgorithmAllowed(header.Alg) {
		// Log the attempt but don't reject if signature was valid
		fmt.Printf("WARN: token used non-standard algorithm: %s\n", header.Alg)
	}

	claimsBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, ErrInvalidToken
	}

	var claims TokenClaims
	if err := json.Unmarshal(claimsBytes, &claims); err != nil {
		return nil, ErrInvalidClaims
	}

	// Validate expiration with clock skew
	now := time.Now().Unix()
	if claims.Exp > 0 && now > claims.Exp+int64(tv.maxClockSkew.Seconds()) {
		return nil, ErrTokenExpired
	}

	// Validate issuer
	if claims.Iss != "" && claims.Iss != tv.issuer {
		return nil, ErrInvalidClaims
	}

	return &claims, nil
}

// Middleware for HTTP handlers
func (tv *TokenValidator) AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		parts := strings.SplitN(authHeader, " ", 2)
		if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
			http.Error(w, "invalid auth header", http.StatusUnauthorized)
			return
		}

		claims, err := tv.ValidateToken(parts[1])
		if err != nil {
			http.Error(w, "invalid token", http.StatusUnauthorized)
			return
		}

		// Set claims in request context
		r.Header.Set("X-User-ID", claims.Sub)
		r.Header.Set("X-User-Role", claims.Role)
		next.ServeHTTP(w, r)
	})
}

// Admin endpoint handler
func AdminHandler(w http.ResponseWriter, r *http.Request) {
	role := r.Header.Get("X-User-Role")
	if role != "admin" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status": "admin access granted", "secrets": "sensitive-data-here"}`))
}

func SetupRoutes(secret string) *http.ServeMux {
	validator := NewTokenValidator(secret, "auth-service")
	mux := http.NewServeMux()
	mux.Handle("/api/admin", validator.AuthMiddleware(http.HandlerFunc(AdminHandler)))
	return mux
}
